/* แกะผู้ส่ง บริษัท ระบบ และวันที่จากหัวข้อเมล */
const COMPANIES = ['3XB', 'AT4', 'SK8', 'FR8', 'MC8', 'MR9', 'AZ8', 'CY8', 'UFABET7M'];
const SOURCES = {}; // รายละเอียดผู้ส่งจริงอยู่ในตาราง mail_sources เท่านั้น
const emailOf = (value) => { const m=String(value||'').toLowerCase().match(/[a-z0-9._%+-]+@[a-z0-9.-]+\.[a-z]{2,}/); return m ? m[0] : ''; };
function parseSubject(subject) {
  const s=String(subject||''); let company=null;
  for(const c of COMPANIES) if(new RegExp('\\b'+c+'\\b','i').test(s)){ company=c; break; }
  if(!company){ const m=s.match(/(?:Fwd:\s*)?\b([A-Z]{2,4}\d{0,2})\b/); if(m) company=m[1].toUpperCase(); }
  let businessDate=null; const candidates=[...s.matchAll(/(\d{1,2})[-/](\d{1,2})[-/](\d{2,4})/g)];
  for(const d of candidates){ const day=Number(d[1]),month=Number(d[2]); if(day<1||day>31||month<1||month>12) continue; let y=Number(d[3]); if(y<100)y+=2500; if(y>2400)y-=543; businessDate=`${y}-${String(month).padStart(2,'0')}-${String(day).padStart(2,'0')}`; break; }
  return {company,businessDate,isSupplement:/เพิ่มเติม/.test(s)};
}
const out=[];
for(const item of $input.all()){
  const j=item.json,headers=j.headers||{},subject=j.Subject||j.subject||headers.subject||'',sender=headers.from||j.From||j.from||'';
  const meta=parseSubject(subject),sourceEmail=emailOf(sender),source=SOURCES[sourceEmail];
  let businessSystem=source&&source.systems.length===1?source.systems[0]:null;
  if(/UFABET7M|7M/i.test(subject)) businessSystem='UFABET7M'; else if(/(?:ระบบ\s*)?123|SK8|AT4|FR8|MC8|MR9/i.test(subject)) businessSystem='SYS123'; else if(/XXX|3XB/i.test(subject)) businessSystem='XXX';
  const binaryKeys=Object.keys(item.binary||{});
  out.push({json:{gmail_message_id:j.id,gmail_thread_id:j.threadId,mailbox:headers.to||j.to||'',label:'AUDIT 2',subject,sender,source_email:sourceEmail||null,source_name:source?source.name:null,business_system:businessSystem,received_at:j.internalDate?new Date(Number(j.internalDate)).toISOString():new Date().toISOString(),company:meta.company,business_date:meta.businessDate,is_supplement:meta.isSupplement,file_count:binaryKeys.length,status:'new',binaryKeys},binary:item.binary});
}
return out;

/* จับคู่ batch_id แล้วแตกไฟล์แนบเป็นทีละ item */
const batches = $input.all();
const source = $('แกะบริษัทและวันที่จากหัวข้อ').all();
const out = [];
batches.forEach((b, i) => {
  const rows = Array.isArray(b.json) ? b.json : (b.json.body || [b.json]);
  const row = Array.isArray(rows) ? rows[0] : rows;
  const src = source[i];
  if (!src) return;
  Object.keys(src.binary || {}).forEach((key, attachmentIndex) => {
    const bin = src.binary[key];
    out.push({ json: { batch_id: row.id, business_date: src.json.business_date, company: src.json.company, subject: src.json.subject, gmail_message_id: src.json.gmail_message_id, attachment_index: attachmentIndex, file_name: bin.fileName || key, mime_type: bin.mimeType || 'application/octet-stream', is_zip: /\.zip$/i.test(bin.fileName || key) }, binary: { data: bin } });
  });
});
return out;

/* แยกไฟล์ใน zip และตัดไฟล์ระบบของ macOS */
const OK = /\.(xlsx|xlsm|xls|csv|txt|pdf|docx)$/i;
const out = [];
for (const item of $input.all()) {
  const parent = item.json;
  Object.entries(item.binary || {}).forEach(([key, bin], zipIndex) => {
    const name = bin.fileName || key;
    if (/^__MACOSX|\/\._|^\._|\.DS_Store$/.test(name) || !OK.test(name)) return;
    out.push({ json: { batch_id: parent.batch_id, business_date: parent.business_date, company: parent.company, subject: parent.subject, gmail_message_id: parent.gmail_message_id, attachment_index: `${parent.attachment_index || 0}-${zipIndex}`, file_name: name.split('/').pop(), from_zip: parent.file_name, mime_type: bin.mimeType || 'application/octet-stream' }, binary: { data: bin } });
  });
}
return out;

/* เดาชนิดไฟล์และสร้าง Storage path แบบ ASCII-safe */
function kindOf(name, subject) {
  const n = String(name || '');
  const s = String(subject || '');
  if (/รายงานหน้า\s*BO/i.test(s) && /\.(xlsx|xlsm?|csv)$/i.test(n)) return 'bo_main';
  if (/\.pdf$/i.test(n)) return /ฝาก\s*[-–—/]?\s*ถอน|ฝากถอน|statement|(^|[^a-z0-9])stm([^a-z0-9]|$)/i.test(n) ? 'stm_pdf' : 'doc_clarify';
  if (/\.docx?$/i.test(n)) return 'doc_clarify';
  if (/รายงานบัญชี(ฝาก|ถอน)|(^|[^a-z0-9])BO([^a-z0-9]|$)/i.test(n)) return 'bo_main';
  if (/ฝากมือ.*เครดิต/.test(n)) return 'manual_credit';
  if (/ฝากมือ.*Payment/i.test(n)) return 'manual_payment';
  if (/ฝากมือ.*โบนัส/.test(n)) return 'manual_bonus';
  if (/ขอถอนค่าคอม/.test(n)) return 'comm_req';
  if (/ถอนเครดิต/.test(n)) return 'credit_out';
  if (/\.(xlsx|xlsm?|csv)$/i.test(n) && (/รายงาน\s*PM/i.test(s) || /AUTOPEER|CYBER|AZPAY|MYPAY|12PAY|CPXM/i.test(n))) return 'pm_statement';
  return 'unknown';
}
function companyOf(name, current) {
  const n = String(name || '');
  const rules = [['3XB', /(^|[^A-Z0-9])3X(BET|B)?([^A-Z0-9]|$)/i], ['AT4', /(^|[^A-Z0-9])AT4([^A-Z0-9]|$)/i], ['FR8', /(^|[^A-Z0-9])FR8([^A-Z0-9]|$)/i], ['SK8', /(^|[^A-Z0-9])SK8?([^A-Z0-9]|$)/i], ['MR9', /(^|[^A-Z0-9])MR9?([^A-Z0-9]|$)/i], ['MC8', /(^|[^A-Z0-9])MC8?([^A-Z0-9]|$)/i], ['UR9', /(^|[^A-Z0-9])UR9([^A-Z0-9]|$)/i], ['PS8', /(^|[^A-Z0-9])PS8([^A-Z0-9]|$)/i], ['UFABET7M', /UFABET7M|(^|[^A-Z0-9])(?:UFA)?7M([^A-Z0-9]|$)/i]];
  for (const [company, pattern] of rules) if (pattern.test(n)) return company;
  return current || null;
}
const ascii = (s) => String(s || '').replace(/[^A-Za-z0-9._-]/g, '_');
function sizeBytes(value) {
  if (typeof value === 'number') return value;
  const m = String(value || '').match(/([\d.]+)\s*(B|kB|MB|GB)?/i);
  if (!m) return null;
  const factor = { b: 1, kb: 1024, mb: 1048576, gb: 1073741824 }[(m[2] || 'b').toLowerCase()] || 1;
  return Math.round(Number(m[1]) * factor);
}
return $input.all().map((item, index) => {
  const j = item.json;
  const date = j.business_date || 'unknown-date';
  const company = companyOf(j.file_name, j.company);
  const messageId = j.gmail_message_id || j.batch_id || 'unknown-message';
  const ordinal = String(j.attachment_index ?? index).padStart(3, '0');
  const extMatch = String(j.file_name || '').match(/\.([A-Za-z0-9]{1,10})$/);
  const ext = (extMatch ? extMatch[1] : 'bin').toLowerCase();
  const path = [ascii(date), ascii(company || 'UNKNOWN'), ascii(messageId), ascii(ordinal) + '.' + ext].join('/');
  const bin = (item.binary || {}).data || {};
  return { json: { ...j, company, kind: kindOf(j.file_name, j.subject), storage_path: path, size_bytes: sizeBytes(bin.fileSize) }, binary: item.binary };
});
